+fn poll(stop: Option<&dyn StopSignal>) -> Result<(), RoleHierarchyError> {
+    if stop.is_some_and(StopSignal::stopped) {
+        Err(RoleHierarchyError::Stopped)
+    } else {
+        Ok(())
+    }
+}
