+impl std::error::Error for RoleHierarchyError {
+    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
+        match self {
+            Self::Storage(error) => Some(error),
+            Self::Graph(error) => Some(error),
+            _ => None,
+        }
+    }
+}
